func:
// Everything the list node offers in its dialog can also arrive with the message, and what arrives
// wins over what is configured. So one configured node can serve a flow that reads different things,
// and this Function node is where that choice lives.
//
// Leave a field out - or delete this node - to use the node's own settings instead.
msg.payload = {
    what: 'messages', // "Read":      messages | dialogs | participants
    peer: 'me', // "Read from": a username, a chat id, or "me" for your own Saved Messages
    limit: 50, // "Limit":     0 means everything, which on a busy chat can earn a FLOOD_WAIT
    mode: 'stream', // "Output":    stream = one message per item, array = one message with all of them
    // search: 'invoice',        // only messages and participants can be searched
};

return msg;
